// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: an arbitrary actor address (will be treated as EOA by the fuzzer) and an adversarial attacker index
    function testFuzz_property(address actor) public {
        // keep actor in wide but valid domain (non-zero)
        vm.assume(actor != address(0));

        // Ensure actor has ETH so it can call if needed (not strictly necessary, but safe)
        vm.deal(actor, 1 ether);

        // First call: actor calls airDrop and should get +20 tokens on the reference implementation.
        // We call via vm.prank to simulate the external caller.
        vm.prank(actor);
        bool ok1;
        try c.airDrop() {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // Read token balance for actor after the first call
        uint balAfterFirst = c.tokenBalance(actor);

        // Second call: actor calls airDrop again. On the reference it should succeed as long as hasNoBalance prevents double airdrop
        // Note: hasNoBalance requires zero balance, so second call on reference will revert; however the concrete distinguishing rule
        // we assert is that the reentrancy lock is not permanently set so other callers' balances are unaffected. To detect the mutant's
        // permanent lock, we perform a second call from a different actor and check that their balance is still the expected value after one airdrop.

        // Choose a second actor different from the first
        address actor2 = address(uint160(uint256(keccak256(abi.encodePacked(actor, "salt")))));
        vm.assume(actor2 != address(0));
        vm.assume(actor2 != actor);
        vm.deal(actor2, 1 ether);

        // Actor2 performs airDrop once
        vm.prank(actor2);
        bool ok2;
        try c.airDrop() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        uint balActor2 = c.tokenBalance(actor2);

        // GENERAL ASSERTION (single assertTrue): On the reference implementation for ANY actor/address the contract
        // allows a fresh caller to receive 20 tokens (i.e., their tokenBalance equals 20 after a successful airDrop call).
        // The mutant that never resets the reentrancy lock can permanently block airDrop for subsequent callers, causing balActor2 == 0
        // for some inputs; thus we assert that if the second call returned true then the balance must be 20.

        // This reads only c's public getter and the observed success flag of the external call.
        assertTrue(!(ok2) || (balActor2 == 20));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: callerA and callerB are adversarially chosen by the fuzzer.
    // We keep domain wide: require they are distinct EOAs (fuzzer can choose same, but we assume distinct to exercise the interleaving).
    function testFuzz_property(address callerA, address callerB) public {
        // Keep addresses non-zero and distinct to produce meaningful separate actors
        vm.assume(callerA != address(0));
        vm.assume(callerB != address(0));
        vm.assume(callerA != callerB);

        // Fund both actors so they can make external calls if needed by C (not used here but safe)
        vm.deal(callerA, 1 ether);
        vm.deal(callerB, 1 ether);

        // First, have callerA call airDrop which should succeed on the reference and set tokenBalance[A] = 20
        vm.startPrank(callerA);
        // airDrop requires supportsToken to compare keccak256 against Bank(msg.sender).supportsToken()
        // The contract's supportsToken() expects the msg.sender to be a Bank contract returning keccak256("Nu Token").
        // The reference C's supportsToken modifier does: Bank(msg.sender).supportsToken() == keccak256("Nu Token").
        // To satisfy this, we deploy a minimal Bank-like helper per-call that returns the expected bytes32.
        vm.stopPrank();

        // Deploy helper banks for callerA and callerB and have them call through via tx.origin-like pattern: c checks msg.sender, so we must have the Bank contract call c.
        BankCaller bankA = new BankCaller(address(c));
        BankCaller bankB = new BankCaller(address(c));

        // Make bankA call airDrop on behalf of callerA by using tx.origin-like property: we will prank the bank contract's caller to be callerA
        vm.prank(address(bankA)); // simulate that callerA is the tx origin is not possible; instead, C's supportsToken uses msg.sender (the bank contract) so bank contract itself should call c
        // We need the bank contract to call c while its own code returns the expected supportsToken(); bankA is set up to call c.airDrop() from its own address.
        // So simply call bankA.callAirdrop() which executes c.airDrop() with msg.sender == address(bankA)
        // But we want the actor identities (callerA/callerB) to be distinct actors that are recorded in tokenBalance mapping — tokenBalance uses msg.sender of airDrop, which will be the bank contract address.
        // To link tokenBalance keys to fuzzed addresses, instead of requiring tokenBalance keyed by EOA, we accept that tokenBalance key will be the bank contract addresses. To introduce the fuzzed addresses into choice, we deploy bank contracts deterministically influenced by fuzzed addresses via prank when deploying.

        // Deploy bankA with creator callerA so its address depends on callerA (make deployment under prank)
        vm.prank(callerA);
        BankCaller bankA2 = new BankCaller(address(c));
        vm.prank(callerB);
        BankCaller bankB2 = new BankCaller(address(c));

        // Now bankA2 calls airDrop (msg.sender == bankA2) and satisfies supportsToken since BankCaller.supportsToken returns keccak256("Nu Token")
        bankA2.callAirdrop();

        // Record balances after first successful airdrop by bankA2
        uint balA_after = c.tokenBalance(address(bankA2));

        // Now attempt a subsequent airdrop by bankB2 which should still succeed on reference contract (and increase tokenBalance(bankB2) by 20)
        bool ok;
        try bankB2.callAirdrop() {
            ok = true;
        } catch {
            ok = false;
        }

        uint balB_after = c.tokenBalance(address(bankB2));

        // General assertion: on the correct contract, after any successful first airdrop by some bank actor, a later airdrop by another valid bank actor remains possible and increases their balance by 20.
        // We express this as: if bankA2's balance is 20 (it succeeded), then bankB2's balance should be 20 as well (the subsequent call should succeed).
        // This property holds for the reference; the mutant that leaves the lock set will make ok==false and balB_after==0 for some inputs.
        assertTrue(!(balA_after == 20) || (ok && balB_after == 20));
    }
}

// Minimal helper that acts as a Bank and can call C.airDrop; returns the expected supportsToken() value.
contract BankCaller {
    C public c;
    constructor(address _c) { c = C(_c); }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirdrop() external {
        c.airDrop();
    }
}

