pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: two addresses. We will treat `initialHolder` as the address
    // that we give an initial non-zero balance, and `caller` as the address that
    // will invoke airDrop. The reference requires that if initialHolder has a
    // non-zero balance, then calling airDrop (by any caller) does not change
    // initialHolder's balance (because airDrop has hasNoBalance and only adds
    // to the caller when caller had zero). The mutant removes that guard so it
    // can increase balances of addresses that already had tokens.
    function testFuzz_property(address initialHolder, address caller) public {
        // keep addresses non-zero and distinct to avoid trivial zero-address cases
        vm.assume(initialHolder != address(0));
        vm.assume(caller != address(0));

        // Ensure initialHolder has a non-zero balance by having them receive an airdrop
        // in the reference: airDrop requires caller had zero balance, so call as initialHolder
        // and it will succeed (gives +20). Use prank to act as initialHolder.
        vm.prank(initialHolder);
        c.airDrop();
        uint256 before = c.tokenBalance(initialHolder);
        // before should be non-zero under reference (20)
        vm.assume(before != 0);

        // Now call airDrop as `caller`. Under the reference, this may increase caller's balance
        // only if caller had zero before; in any case, the reference's hasNoBalance prevents
        // changing balances of other addresses like initialHolder. We capture initialHolder's
        // balance after the call and assert it is unchanged.
        vm.prank(caller);
        c.airDrop();

        uint256 after = c.tokenBalance(initialHolder);

        // Single invariant: initialHolder's tokenBalance is unchanged by another caller's airDrop
        // (reference: true for all inputs; mutant: can be violated for some inputs)
        assertTrue(after == before);
    }
}

