pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an address actor (the caller of airDrop) and a nonzero initialBalanceSeed
    function testFuzz_property(address actor, uint256 initialBalanceSeed) public {
        // keep actor non-zero and not the zero address
        vm.assume(actor != address(0));
        // bound the seed to a small non-zero value to make balances realistic but leave wide domain
        uint256 seed = bound(initialBalanceSeed, 1, 1e18);

        // We need to simulate that actor already has a non-zero tokenBalance in the reference contract.
        // tokenBalance is public so we cannot write to it directly; but we can simulate by calling airDrop
        // from a supportive contract until it becomes non-zero. However, airDrop requires supportsToken check
        // that reads Bank(msg.sender).supportsToken(). So we deploy a helper Bank-like contract whose
        // supportsToken returns the expected bytes32 and then call airDrop via vm.prank to that helper.

        // Deploy a helper that reports support for the token
        BankLike helper = new BankLike();

        // Make actor act as the helper by having the helper call airDrop on behalf of actor
        // But supportsToken uses msg.sender inside C, so we must have the helper be msg.sender when C.airDrop runs.
        // We'll fund actor and then have actor call via vm.prank -> but msg.sender must be actor and Bank(msg.sender).supportsToken()
        // needs to be callable on actor (i.e., actor must have code). Since fuzzed addresses are EOAs, we instead deploy
        // a helper that is both the caller and reports support. So we will treat 'actor' as the intended identity but
        // actually use the helper contract as the caller to create the non-zero balance for the actor substitute.

        // Use helper as the caller to create an initial non-zero balance
        vm.prank(address(helper));
        c.airDrop();

        // Verify helper (the caller) now has non-zero balance
        uint256 before = c.tokenBalance(address(helper));
        // ensure we did create a non-zero balance (should be 20)
        vm.assume(before != 0);

        // Now we want to test the property about a caller with a pre-existing non-zero balance: we will use the same helper
        // as the caller. The invariant: in the reference, any caller with non-zero tokenBalance cannot receive more via airDrop.
        // So calling airDrop again from helper should revert because of hasNoBalance (or otherwise not increase balance).

        // Call airDrop again as helper and observe whether the call succeeded (ok==true) or reverted (ok==false).
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract enforces hasNoBalance, so the second call from the same caller with non-zero balance must fail (ok==false).
        // The mutant removed hasNoBalance so for some inputs the second call will succeed (ok==true). We assert the universal property
        // that for EVERY admissible input the reference yields ok == false. This single assert reads c via its behavior.
        assertTrue(ok == false);
    }
}

// Minimal helper that reports support for the token string when called as Bank(msg.sender).supportsToken()
contract BankLike {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

