pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Adversarial caller contract that implements supportsToken() and can pre-set its tokenBalance
contract Supporter {
    // Return the keccak256 of "Nu Token" to satisfy supportsToken check
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: address callerAddr (we'll ignore raw address and deploy a contract), uint256 initialBalance
    function testFuzz_property(address /*unused*/, uint256 initialBalance) public {
        // Keep domain wide but restrict to a reasonable size to avoid overflow in the contract's add
        // (the contract uses a simple +20 check; keep initialBalance bounded below max(uint)
        initialBalance = bound(initialBalance, 0, type(uint256).max - 100);

        // Deploy an adversarial contract that satisfies supportsToken
        Supporter supporter = new Supporter();

        // We need to make supporter appear as msg.sender in calls to c.airDrop.
        // First, set an initial tokenBalance for the supporter by calling airDrop from supporter when allowed.
        // The reference contract requires initial balance == 0 to succeed. So to create a preexisting non-zero
        // balance on the reference, we must bypass hasNoBalance — we cannot. Instead, we emulate the admissible
        // scenario by directly modifying storage is NOT allowed. Therefore we will call airDrop once from supporter
        // (succeeds only when balance==0) and then, if initialBalance > 0, we simulate depositing additional tokens
        // by calling airDrop additional times through the same supporter under trust that reference prohibits it.
        // To create a pre-existing non-zero balance in an admissible way for both contracts, we perform multiple
        // calls from the supporter until we reach initialBalance by repeating airDrop where possible. However,
        // on the reference only the first call will succeed; on the mutant subsequent calls may succeed. To craft a
        // precondition that the reference enforces (balance==0) for all calls, instead we will set up the initial
        // balance by directly interacting with the public mapping via the mutant path cannot be done here. The safe
        // and correct approach: if initialBalance == 0, the reference allows airDrop once; if initialBalance > 0,
        // the reference will never permit creating that precondition by repeated airDrop — so we instead use the
        // test's single assertion form: after attempting to call airDrop from supporter when its balance is non-zero,
        // the reference must revert (i.e., the call must fail), whereas the mutant may succeed. We therefore first
        // make the supporter obtain a non-zero balance by performing one successful airDrop (allowed when balance==0),
        // then we attempt another airDrop and observe behavior. This sequence is admissible for both contracts: both
        // allow the first call; the difference arises on the second call when initialBalance>0.

        vm.prank(address(supporter));
        // First call: should succeed on both reference and mutant (starting from zero)
        c.airDrop();

        // Now supporter has tokenBalance == 20 under reference and mutant. We may fuzz whether we attempt a second
        // call or not: we only care when pre-existing balance is non-zero. Use the fuzzed initialBalance as a flag:
        // if initialBalance == 0 then we skip the second attempt and assert the reference still allows the first.
        // If initialBalance > 0 we attempt a second airDrop from the same supporter: reference must revert due to hasNoBalance,
        // mutant may succeed and increase the balance.

        bool ok;
        if (initialBalance == 0) {
            // After a single successful airDrop, tokenBalance(supporter) == 20 on reference.
            // Assert that calling airDrop once succeeded: read the balance getter to check it's 20.
            uint256 bal = c.tokenBalance(address(supporter));
            ok = (bal == 20);
        } else {
            // Attempt a second airDrop from supporter: reference should revert (hasNoBalance) because balance != 0.
            // Capture success/failure via try/catch on an external call.
            vm.prank(address(supporter));
            try c.airDrop() {
                ok = true; // mutant may allow this and return
            } catch {
                ok = false; // reference will revert here
            }
        }

        // The single assertion: if initialBalance == 0 then ok must be true (first airDrop succeeded and balance is 20).
        // If initialBalance > 0 then ok must be false on the reference (second airDrop reverts because of hasNoBalance).
        // This is a universal property: for every fuzzed initialBalance the reference satisfies this, while the mutant
        // (which removed hasNoBalance) will have some initialBalance>0 for which ok becomes true, causing the test to fail.
        assertTrue(ok);
    }
}

