pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Helper contract that implements supportsToken() and can pre-seed its tokenBalance by calling airDrop via a special setup path.
    // It exposes a function to call c.airDrop() as itself.
    contract CallerHelper {
        C public target;
        constructor(C _target) {
            target = _target;
        }
        // Return the expected bytes32 for supportsToken
        function supportsToken() external pure returns (bytes32) {
            return keccak256(abi.encodePacked("Nu Token"));
        }
        // Call airDrop on target
        function doAirDrop() external {
            target.airDrop();
        }
    }

    function setUp() public { c = new C(); }

    // Fuzz parameters: an address seed and a small nonzero initial number to help guide fuzzer (we will use as a boolean flag via bound)
    function testFuzz_property(address seed, uint256 nonzeroFlag) public {
        // Keep domain wide but ensure nonzeroFlag can indicate we want to pre-seed balance
        nonzeroFlag = bound(nonzeroFlag, 0, 1);

        // Deploy a helper contract which will act as the caller (must be a contract so supportsToken() is available)
        CallerHelper helper = new CallerHelper(c);

        // If nonzeroFlag==1 we want to pre-seed the helper's tokenBalance to be non-zero in the reference scenario.
        // To pre-seed, we need to bypass hasNoBalance in the reference; we cannot do that, so instead we simulate
        // pre-seeding by directly manipulating state via calling airDrop from the helper only under the mutant — but
        // because tests run against the reference contract first, we instead use vm.prank with the helper to attempt
        // to call airDrop and condition on its success. The goal of the universal property: whenever helper already has
        // a non-zero balance, reference must revert on further airDrop calls. So we attempt to make helper obtain a
        // non-zero balance by calling airDrop; if that succeeds (it can only succeed on mutant), the subsequent assertion
        // should detect divergence. To keep admissible domain (so reference still holds for ALL admissible inputs), we
        // only assert the reference behavior: if helper already has non-zero balance then another airDrop call should revert.

        // First, try to call airDrop once to see if helper can obtain a non-zero balance. This will succeed under mutant,
        // but will revert under reference because hasNoBalance is present only for initial non-zero check. We catch both outcomes.
        bool firstOk;
        try helper.doAirDrop() {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // Now read helper's balance from c
        uint256 bal = c.tokenBalance(address(helper));

        // If helper has a non-zero balance now (this can only be true under the mutant), then the reference guarantees
        // that any further call from the same helper to airDrop would revert. We perform that call and assert the reference property:
        bool secondOk;
        try helper.doAirDrop() {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // The single assertion: in the correct contract, whenever a contract-caller already has a non-zero tokenBalance,
        // further calls to airDrop must revert (so secondOk must be false). The mutant removing hasNoBalance allows a
        // contract caller with non-zero balance to successfully call airDrop again, making secondOk true. This assertion
        // reads c via its public getter tokenBalance and the call outcome of airDrop through try/catch.
        assertTrue(!(bal != 0 && secondOk));
    }
}

