contract InvMutTest is Test {
    C c;

    // Helper Bank implementation that advertises support for "Nu Token"
    contract GoodBank {
        function supportsToken() external pure returns (bytes32) {
            return keccak256(abi.encodePacked("Nu Token"));
        }
    }

    function setUp() public { c = new C(); }

    // Fuzzed parameter: an arbitrary caller address that will be the msg.sender when calling airDrop
    function testFuzz_property(address caller) public {
        // Keep caller non-zero to be a valid actor
        vm.assume(caller != address(0));

        // Deploy a GoodBank that returns the expected token name
        GoodBank good = new GoodBank();

        // Ensure the caller has no prior balance in the contract (the hasNoBalance modifier requires 0)
        // No setup required because fresh contract has zero balances for all addresses

        // Make the call originate from `caller` and have msg.sender be the GoodBank contract
        // The C contract expects Bank(msg.sender).supportsToken(), so we need msg.sender to be the Bank.
        // We accomplish this by making the GoodBank call into C while setting tx.origin to caller.
        // To simulate that, we have the GoodBank call C.airDrop via an intermediate helper that sets tx.origin.
        // However, in Solidity tests we cannot arbitrarily set tx.origin. Instead, we use vm.prank to make the
        // immediate caller be the GoodBank contract and use vm.prank to set tx.origin as `caller` while
        // performing the external call: vm.prank(caller, address(good)) would make msg.sender==address(good) and tx.origin==caller.

        // Use vm.prank(origin, msg.sender) to simulate GoodBank being msg.sender and caller being tx.origin
        vm.prank(caller, address(good));
        // Call airDrop; it will execute with msg.sender == address(good)
        // Wrap in try/catch to record whether call succeeded; correct contract should succeed and increase tokenBalance(tx.origin)
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference contract guarantees that when Bank(msg.sender).supportsToken()
        // returns keccak256("Nu Token"), the airdrop succeeds for the originating caller and increases their balance by 20.
        // We observed success via `ok`. Now assert that ok implies the caller's balance is 20, and that the reference
        // will succeed (ok==true). For the universal property across all inputs we assert that if the GoodBank (which we used)
        // is the msg.sender, the call succeeds (ok==true). This will fail for the mutant which compares against "Other Token".

        // Single required assertion: reference always allows this airdrop (ok must be true)
        assertTrue(ok);
    }
}

