        // ensure caller is bank contract, since supportsToken checks Bank(msg.sender).supportsToken()
        address callerAddr = address(bank);

        // Ensure tokenBalance[callerAddr] == 0 initially
        assertEq(c.tokenBalance(callerAddr), 0);

        // Act: have callerAddr call airDrop
        vm.prank(callerAddr);
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees that for any caller with initial balance 0, airDrop succeeds and sets balance to 20.
        // So assert that either the call reverted (which would indicate modifier failed) is false and the resulting balance is 20.
        // We must produce exactly one assertTrue reading c. Construct the boolean reading c.tokenBalance and compare to 20.
        // Compose the property into one boolean: call succeeded AND tokenBalance == 20.
        bool prop = ok && (c.tokenBalance(callerAddr) == 20);
        assertTrue(prop);
    }
}

contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return(keccak256(abi.encodePacked("Nu Token")));
    }
}

